import { useSuspenseQuery } from '@tanstack/react-query';
import { createFileRoute, useNavigate } from '@tanstack/react-router';
import { useCallback } from 'react';

import { useModal } from '@/hooks/useModal';
import { getAccountMeQueryOptions } from '@/query/options/account';
import { useStartFlow } from '@/routes/_authenticated/start/-startFlow.context';
import { Step1SelectTemplate } from '@/routes/_authenticated/start/-components/steps/Step1SelectTemplate';
import {
  isFreeDraftTemplate,
  type DraftTemplateOption
} from '@/routes/_authenticated/start/-components/steps/draftTemplateProfile';
import { FreeTrialExhaustedModal } from '@/routes/_authenticated/credit-plan/-components/InsufficientCreditModal/FreeTrialExhaustedModal';
import { AllCreditsExhaustedModal } from '@/routes/_authenticated/credit-plan/-components/InsufficientCreditModal/AllCreditsExhaustedModal';

export const Route = createFileRoute('/_authenticated/start/template/')({
  component: RouteComponent
});

function RouteComponent() {
  const navigate = useNavigate();
  const modal = useModal();
  const { data: me } = useSuspenseQuery(getAccountMeQueryOptions());
  const {
    draftTemplates,
    isDraftTemplatesLoading,
    isDraftTemplatesError,
    refetchDraftTemplates,
    selectedTemplateFileId,
    setSelectedDraftTemplate
  } = useStartFlow();

  const checkCreditBeforeAction = useCallback(
    (template: DraftTemplateOption): boolean | 'pending' => {
      if (isFreeDraftTemplate(template)) {
        return true;
      }

      if (!me.canCreateDraftExport) {
        modal.openModal(({ isOpen, onClose }) => (
          <FreeTrialExhaustedModal isOpen={isOpen} onClose={onClose} />
        ));
        return 'pending';
      }

      if (!me.hasProAccess) {
        return true;
      }

      const hasAvailableCredit =
        me.freeCredit >= me.productExportCredit || me.paidCredit > 0;

      if (!hasAvailableCredit) {
        modal.openModal(({ isOpen, onClose }) => (
          <AllCreditsExhaustedModal isOpen={isOpen} onClose={onClose} />
        ));
        return 'pending';
      }

      return true;
    },
    [me, modal]
  );

  const handleSelectTemplate = useCallback(
    (template: DraftTemplateOption) => {
      if (checkCreditBeforeAction(template) !== true) {
        return;
      }

      setSelectedDraftTemplate(template);
      navigate({ to: '/start/prompt' });
    },
    [checkCreditBeforeAction, navigate, setSelectedDraftTemplate]
  );

  return (
    <Step1SelectTemplate
      templates={draftTemplates}
      isLoading={isDraftTemplatesLoading}
      isError={isDraftTemplatesError}
      selectedTemplateId={selectedTemplateFileId}
      onRetry={() => {
        void refetchDraftTemplates();
      }}
      onSelectTemplate={handleSelectTemplate}
    />
  );
}
